// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 newMin) internal {
        try c.SetMinSum(newMin) {} catch { return; }
        uint256 observed;
        try c.MinSum() returns (uint256 __r) { observed = __r; } catch { return; }
        assertTrue(observed == newMin);
    }

    function testFuzz_run(uint256 newMin) public {
        _run(newMin);
    }

    receive() external payable {}
}
